text:
Wanda rents windsurf boards and Kit rents kiteboards on the same beach. Each rental costs its owner $10, and each picks a high price, \(H = \$36\), or a low price, \(L = \$20\). Each firm has 30 customers who prefer its sport: loyal customers rent from it at any price, price-sensitive ones pay \(H\) but switch if the other firm is cheaper, and 10 price-driven ones pay \(L\) but not \(H\).
Move the slider to change how many of each firm’s customers are loyal, and pick each firm’s price. The customers walk to the stand they rent from, and the pay-off matrix below updates.

viewof loyal = Inputs.range([0, 20], {step: 1, value: 11, label: "Loyal customers per firm"})
viewof wanda = Inputs.radio(new Map([["H ($36)", "H"], ["L ($20)", "L"]]), {label: "Wanda's price", value: "L"})
viewof kit = Inputs.radio(new Map([["H ($36)", "H"], ["L ($20)", "L"]]), {label: "Kit's price", value: "L"})























md`Each firm: **${loyal} loyal**, **${20 - loyal} price-sensitive**, and **10 price-driven** customers.`







model = {
  const price = {H: 36, L: 20};
  const cost = 10;
  const label = {loyal: "loyal", sens: "price-sensitive", drive: "price-driven"};
  const other = f =&gt; f === "Wanda" ? "Kit" : "Wanda";
  // Where a group rents: its own firm, the other firm, or nobody (null).
  function where(owner, grp, p) {
    const mine = p[owner], theirs = p[other(owner)];
    if (grp === "loyal") return owner;
    if (grp === "sens") return (mine === "H" && theirs === "L") ? other(owner) : owner;
    return mine === "L" ? owner : (theirs === "L" ? other(owner) : null);
  }
  function blocks(l, p) {
    const n = {loyal: l, sens: 20 - l, drive: 10};
    const out = [];
    for (const owner of ["Wanda", "Kit"])
      for (const grp of ["loyal", "sens", "drive"])
        out.push({id: owner + "-" + grp, owner, grp, n: n[grp], at: where(owner, grp, p)});
    return out;
  }
  const count = (bs, firm) =&gt; bs.filter(b =&gt; b.at === firm).reduce((s, b) =&gt; s + b.n, 0);
  function pay(l, w, k) {
    const bs = blocks(l, {Wanda: w, Kit: k});
    return [(price[w] - cost) * count(bs, "Wanda"), (price[k] - cost) * count(bs, "Kit")];
  }
  return {price, cost, label, other, blocks, count, pay};
}







stage = {
  const svg = d3.create("svg").attr("viewBox", [0, 0, 900, 440])
    .attr("width", "100%").style("max-width", "900px").style("height", "auto")
    .attr("role", "img").attr("class", "wk-stage");
  for (const [firm, x, c, sport] of [["Wanda", 10, "#005f94", "windsurf boards"],
                                     ["Kit", 460, "#8f4100", "kiteboards"]]) {
    svg.append("text").attr("x", x + 10).attr("y", 30).attr("fill", c)
      .attr("font-size", 22).attr("font-weight", 700).text(`${firm} (${sport})`);
    svg.append("text").attr("id", `wk-price-${firm}`).attr("x", x + 10).attr("y", 57)
      .attr("font-size", 18).attr("fill", "#1a1a1a");
    svg.append("rect").attr("x", x).attr("y", 70).attr("width", 430).attr("height", 232)
      .attr("rx", 8).attr("fill", "none").attr("stroke", "#595a5b").attr("stroke-width", 2);
    svg.append("text").attr("id", `wk-total-${firm}`).attr("x", x + 10).attr("y", 330)
      .attr("font-size", 19).attr("font-weight", 700).attr("fill", "#1a1a1a");
    svg.append("text").attr("id", `wk-profit-${firm}`).attr("x", x + 10).attr("y", 356)
      .attr("font-size", 18).attr("fill", "#1a1a1a");
  }
  svg.append("text").attr("id", "wk-out-label").attr("x", 20).attr("y", 415)
    .attr("font-size", 18).attr("fill", "#595a5b").text("Do not rent:");
  svg.append("g").attr("id", "wk-blocks");
  svg.append("g").attr("id", "wk-labels");
  return svg.node();
}







live = html`&lt;p class="wk-live" aria-live="polite"&gt;&lt;/p&gt;`







{
  const p = {Wanda: wanda, Kit: kit};
  const bs = model.blocks(loyal, p);
  const X = {Wanda: 20, Kit: 470}, unit = 20, bh = 34, gap = 8, y0 = 82;
  for (const firm of ["Wanda", "Kit"]) {
    // Own customers first, then any who walked over from the other stand.
    const here = bs.filter(b =&gt; b.at === firm && b.n &gt; 0)
      .sort((a, b) =&gt; (a.owner === firm ? 0 : 1) - (b.owner === firm ? 0 : 1));
    here.forEach((b, i) =&gt; { b.x = X[firm]; b.y = y0 + i * (bh + gap); });
  }
  bs.filter(b =&gt; b.at === null && b.n &gt; 0).forEach((b, i) =&gt; { b.x = 140 + i * 230; b.y = 392; });
  bs.filter(b =&gt; b.n === 0).forEach(b =&gt; { b.x = X[b.owner]; b.y = y0; });

  const solid = o =&gt; o === "Wanda" ? "#0072B2" : "#8f4100";
  const tint = o =&gt; o === "Wanda" ? "#dcebf6" : "#f6e4d6";
  const ink = o =&gt; o === "Wanda" ? "#005f94" : "#8f4100";
  const fill = b =&gt; b.grp === "loyal" ? solid(b.owner) : b.grp === "sens" ? "white" : tint(b.owner);
  const text = b =&gt; `${b.n} ${model.label[b.grp]}`;
  const inside = b =&gt; b.n * unit &gt;= text(b).length * 8.6 + 12;
  const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  const svg = d3.select(stage);
  const t = svg.transition().duration(reduce ? 0 : 750);

  svg.select("#wk-blocks").selectAll("rect").data(bs, b =&gt; b.id)
    .join(enter =&gt; enter.append("rect").attr("x", b =&gt; b.x).attr("y", b =&gt; b.y)
                        .attr("width", b =&gt; b.n * unit).attr("height", bh).attr("rx", 3))
    .attr("fill", fill).attr("stroke", b =&gt; solid(b.owner)).attr("stroke-width", 2.5)
    .attr("stroke-dasharray", b =&gt; b.at === null ? "7 4" : null)
    .transition(t)
    .attr("x", b =&gt; b.x).attr("y", b =&gt; b.y).attr("width", b =&gt; b.n * unit)
    .attr("opacity", b =&gt; b.n &gt; 0 ? 1 : 0);

  svg.select("#wk-labels").selectAll("text").data(bs, b =&gt; b.id)
    .join(enter =&gt; enter.append("text").attr("x", b =&gt; b.x).attr("y", b =&gt; b.y + bh / 2))
    .text(text)
    .attr("font-size", 16).attr("font-weight", 700).attr("dominant-baseline", "central")
    .attr("text-anchor", b =&gt; inside(b) ? "middle" : "start")
    .attr("fill", b =&gt; inside(b) && b.grp === "loyal" ? "white" : ink(b.owner))
    .transition(t)
    .attr("x", b =&gt; inside(b) ? b.x + b.n * unit / 2 : b.x + b.n * unit + 8)
    .attr("y", b =&gt; b.y + bh / 2)
    .attr("opacity", b =&gt; b.n &gt; 0 ? 1 : 0);

  const parts = [];
  for (const firm of ["Wanda", "Kit"]) {
    const total = model.count(bs, firm);
    const incoming = bs.filter(b =&gt; b.at === firm && b.owner !== firm).reduce((s, b) =&gt; s + b.n, 0);
    const pr = model.price[p[firm]];
    const profit = (pr - model.cost) * total;
    const from = incoming ? ` (${incoming} from ${model.other(firm)})` : "";
    svg.select(`#wk-price-${firm}`).text(`charges ${p[firm]} = $${pr}`);
    svg.select(`#wk-total-${firm}`).text(`${total} customers${from}`);
    svg.select(`#wk-profit-${firm}`).text(`Profit: (${pr} − 10) × ${total} = ${profit}`);
    parts.push(`${firm} charges ${p[firm]}, $${pr}, and has ${total} customers${from}, for a profit of ${profit}.`);
  }
  const out = bs.filter(b =&gt; b.at === null).reduce((s, b) =&gt; s + b.n, 0);
  svg.select("#wk-out-label").attr("opacity", out ? 1 : 0);
  if (out) parts.push(`${out} price-driven customers do not rent.`);
  const summary = `With ${loyal} loyal customers per firm: ` + parts.join(" ");
  svg.attr("aria-label", "Customers at the two stands. " + summary);
  live.textContent = summary;
}







{
  const P = {};
  for (const w of ["H", "L"]) for (const k of ["H", "L"]) P[w + k] = model.pay(loyal, w, k);
  const flip = x =&gt; x === "H" ? "L" : "H";
  const brW = (w, k) =&gt; P[w + k][0] &gt;= P[flip(w) + k][0];
  const brK = (w, k) =&gt; P[w + k][1] &gt;= P[w + flip(k)][1];
  const nash = ["HH", "HL", "LH", "LL"].filter(c =&gt; brW(c[0], c[1]) && brK(c[0], c[1]));
  const sr = s =&gt; html`&lt;span class="visually-hidden"&gt;${s}&lt;/span&gt;`;
  const cell = (w, k) =&gt; {
    const now = w === wanda && k === kit;
    return html`&lt;td class="${now ? "wk-now" : ""}"&gt;
      &lt;span class="wk-w${brW(w, k) ? " wk-ring" : ""}"&gt;${P[w + k][0]}&lt;/span&gt;${brW(w, k) ? sr(" (Wanda's best response)") : ""}
      &lt;span class="wk-k${brK(w, k) ? " wk-ring" : ""}"&gt;${P[w + k][1]}&lt;/span&gt;${brK(w, k) ? sr(" (Kit's best response)") : ""}
      ${now ? sr(" (the prices chosen above)") : ""}&lt;/td&gt;`;
  };
  const pair = c =&gt; `(${c[0]}, ${c[1]})`;
  const verdict = nash.length === 2
    ? `Two Nash equilibria, ${pair(nash[0])} and ${pair(nash[1])}. Which one happens depends on what each firm expects the other to do.`
    : nash[0] === "HH"
      ? "One Nash equilibrium, (H, H): H is a dominant strategy for both, so both price high."
      : "One Nash equilibrium, (L, L): L is a dominant strategy for both, yet both would earn more at (H, H). A prisoners' dilemma, so both price low.";
  return html`&lt;div class="wk-table freetable table-scroll" role="region" aria-label="Pay-off matrix" tabindex="0"&gt;
  &lt;table&gt;
    &lt;caption&gt;Pay-offs with ${loyal} loyal customers per firm. In each cell, Wanda's profit comes first, in blue, and Kit's second, in orange.&lt;/caption&gt;
    &lt;thead&gt;&lt;tr&gt;&lt;th scope="col"&gt;Wanda's price&lt;/th&gt;&lt;th scope="col"&gt;Kit charges H ($36)&lt;/th&gt;&lt;th scope="col"&gt;Kit charges L ($20)&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;
    &lt;tbody&gt;
      &lt;tr&gt;&lt;th scope="row"&gt;Wanda charges H ($36)&lt;/th&gt;${cell("H", "H")}${cell("H", "L")}&lt;/tr&gt;
      &lt;tr&gt;&lt;th scope="row"&gt;Wanda charges L ($20)&lt;/th&gt;${cell("L", "H")}${cell("L", "L")}&lt;/tr&gt;
    &lt;/tbody&gt;
  &lt;/table&gt;&lt;/div&gt;
  &lt;p&gt;Rings mark each firm's best response to the other's price; a cell with both rings is a Nash equilibrium. The outlined cell is the pair of prices chosen above.&lt;/p&gt;
  &lt;p&gt;&lt;strong&gt;${verdict}&lt;/strong&gt;&lt;/p&gt;`;
}
